          "contrastNote": "↔는 문맥에 따라 품사·뜻이 달라지는 표현입니다. since + 명사구는 시간, as + 명사구는 자격(~로서)입니다. and·or는 단어·구도 연결합니다. 오른쪽 열에는 일반 부사·부사구의 연결 쓰임도 포함합니다.",
