(function(){var concepts=["방식을 꾸미는 단어와 상태를 채우는 보어를 구별합니다. worked tirelessly·replicate colors accurately는 동작 수식, find O ideal·remain high는 상태를 설명하는 형용사입니다.","more/most만 보지 말고 그 뒤 단어의 수식 대상을 봅니다. more effective 자체는 비교급이며, much·far·even·a lot은 비교급 앞의 강조어입니다.","hesitant는 형용사, hesitate는 동사입니다. hard/hardly·high/highly는 모양뿐 아니라 뜻이 달라 문맥에 맞는 결합으로 외웁니다.","whose는 뒤 명사를 소유수식하면서 절을 연결합니다. 비교 대용 that/those는 대신하는 명사의 수를, a/the number of는 주어 전체와 동사 수를 따로 봅니다."];window.HANQ_TOEIC_GRAMMAR_DATA.chapters.forEach(function(c,i){if(i<4)c.focusConcept=concepts[i];});})();

