/* Targeted reasoning: identify real words, then memorize their relation. */
(function(){var n=window.HANQ_TOEIC_GRAMMAR_DATA.chapters;
function lesson(title,concept,en,ko,analysis,remember,focus){return{title:title,concept:concept,en:en,ko:ko,analysis:analysis,remember:remember,focus:focus};}
n[0].focusLessons=[
lesson('① 동작의 방식이면 부사','동사와 목적어가 이미 갖춰진 뒤에도, 그 동작을 어떻게 했는지 덧붙일 수 있습니다. 이때 뒤 단어는 목적어의 상태를 채우는 보어가 아니라 동작을 꾸미는 부사입니다.','The team worked tirelessly and reproduced the colors accurately.','팀은 지칠 줄 모르고 일했고 색상을 정확하게 재현했다.','The team이 두 동작의 주어입니다. tirelessly는 worked를, accurately는 reproduced를 꾸밉니다. colors는 reproduced의 목적어이며 accurately가 colors 자체의 상태를 설명하는 것은 아닙니다.','work tirelessly · reproduce colors accurately',['worked tirelessly','reproduced the colors accurately']),
lesson('② 대상의 상태를 채우면 형용사','remain은 여기서 어떤 상태를 유지하는지 보어를 요구합니다. find도 “찾다”가 아니라 “목적어가 ~하다고 판단하다”일 때 목적어의 상태를 설명하는 보어를 받습니다. 보어에는 명사도 오지만, 아래 문장은 대상의 정체가 아니라 상태를 말합니다.','The director found the plan ideal, and demand remained high.','이사는 그 계획이 이상적이라고 판단했고 수요는 높은 상태를 유지했다.','found의 목적어는 the plan, ideal은 그 계획의 상태입니다. 뒤 절의 주어는 demand이고 high는 수요의 상태입니다. “이상적으로 판단했다/높이 유지했다”라는 동작 방식으로 읽어 ideally/highly를 고르는 자리가 아닙니다.','find + 목적어 + ideal · remain high',['found the plan ideal','demand remained high']),
lesson('③ 목적어 뒤라는 위치만으로 보어를 고르지 않기','빈칸 앞에 목적어가 있어도 동사의 문형과 빈칸의 역할이 먼저입니다. review the plan은 검토 동작의 대상만 정하면 완성되지만, find the plan ideal은 계획에 대한 판단 내용을 채웁니다.','The director reviewed the plan carefully and found it ideal.','이사는 계획을 신중하게 검토했고 그것이 이상적이라고 판단했다.','carefully는 reviewed의 방식입니다. it은 앞의 the plan을 다시 가리키는 found의 목적어이고, ideal은 그 목적어의 상태를 설명합니다. 같은 목적어 뒤에서도 역할이 다릅니다.','review + 목적어 + carefully ↔ find + 목적어 + ideal',['reviewed the plan carefully','found it ideal'])];
n[0].quickRecallTables=[{title:'동작 수식과 상태 보어 · 결합째 암기',headers:['외울 결합','형태 · 뜻 · 판단 대상'],rows:[['work tirelessly','부사 · 지칠 줄 모르고 일하다'],['replicate colors accurately','부사 · 색상을 정확하게 재현하다'],['review the plan carefully','부사 · 계획을 신중하게 검토하다'],['find the plan ideal','형용사 · 계획이 이상적이라고 판단하다'],['remain high','형용사 · 높은 상태를 유지하다'],['rise rapidly','부사 · 빠르게 상승하다'],['an accurate report','형용사 · 정확한 보고서 (report 수식)'],['a highly accurate report','부사 highly → 형용사 accurate → 명사 report']]}];
n[1].focusLessons=[
lesson('① more를 잠시 빼고 수식 대상 찾기','more는 비교를 표시하지만 그 뒤 품사를 결정해 주지는 않습니다. 상태를 설명하면 형용사, 동작 방식을 설명하면 부사입니다. than 뒤 비교 대상은 그다음에 확인합니다.','The new system operates more effectively than the old one.','새 시스템은 기존 시스템보다 더 효과적으로 작동한다.','The new system이 주어, operates가 동사입니다. effectively는 operates를 수식하므로 부사입니다. a more effective system이라면 effective가 명사 system을 직접 꾸미므로 형용사입니다.','operate more effectively ↔ a more effective system',['operates more effectively','than the old one']),
lesson('② most recent와 most recently는 수식 방향이 다름','recent는 명사 앞에서 최근의 것이라고 설명합니다. recently는 갱신 같은 동작이 최근에 이루어졌다고 설명합니다. most가 있어도 recent/recently의 수식 방향은 바뀌지 않습니다.','Please compare our most recent report with the most recently updated file.','가장 최근 보고서와 가장 최근에 갱신된 파일을 비교해 주세요.','첫 명사구는 recent → report입니다. 둘째는 recently → updated → file입니다. recently가 명사 file을 직접 꾸미는 것이 아니라 갱신된 시점을 꾸밉니다.','our most recent report ↔ the most recently updated file',['most recent report','most recently updated file']),
lesson('③ 비교급 자체와 비교급 강조어를 분리','more accurate는 “더 정확한”이라는 비교급 덩어리입니다. 그 앞의 much는 차이가 크다고 강조합니다. 이미 비교급이 있는 자리에 very를 그대로 넣는 실수를 피합니다.','The revised figures are much more accurate than the preliminary estimates.','수정된 수치는 예비 추정치보다 훨씬 더 정확하다.','주어는 The revised figures, 동사는 are, 상태 보어는 more accurate입니다. much는 are를 꾸미거나 비교급을 새로 만드는 말이 아니라 more accurate의 차이를 강조합니다.','very accurate ↔ much more accurate',['much more accurate','than the preliminary estimates'])];
n[2].focusLessons=[
lesson('① hesitant는 상태, hesitate는 동작','hesitant는 형용사라 주어의 상태를 말할 때 be와 함께 씁니다. hesitate는 스스로 동사가 되므로 같은 구조에 be를 덧붙이지 않습니다. to 뒤 행동은 두 표현 모두에 붙을 수 있습니다.','She is hesitant to sign, but she does not hesitate to ask questions.','그녀는 서명은 망설이지만 질문하는 것은 주저하지 않는다.','앞절은 She + is + hesitant입니다. 뒤절은 she + does not hesitate이며 does 뒤의 hesitate는 동사원형입니다. “be hesitate”로 두 구조를 섞지 않습니다.','be hesitant to V ↔ hesitate to V',['is hesitant to sign','does not hesitate to ask']),
lesson('② hard와 hardly는 뜻이 반대 방향','hard 자체가 “열심히”라는 부사로 쓰입니다. hardly는 hard의 방식 부사가 아니라 “거의 ~않다”라는 부정적 의미입니다. 형태가 둘 다 부사로 가능한 자리라면 반드시 뜻까지 봅니다.','The staff work hard, but they hardly have time for a break.','직원들은 열심히 일하지만 쉴 시간은 거의 없다.','hard는 work를 “열심히”로 꾸밉니다. hardly는 have time을 “거의 없다”로 제한합니다. hard에 -ly를 붙이면 더 정확한 부사가 된다는 방식으로 고르지 않습니다.','work hard · hardly have time',['work hard','hardly have time']),
lesson('③ high와 highly는 실제 높이와 정도','high는 높이 올라가는 실제 위치를 나타내는 부사로 쓰일 수 있습니다. highly는 effective/skilled 같은 형용사나 recommended/regarded 같은 평가 표현의 정도를 높입니다.','The drone flew high, and the team was highly satisfied with the images.','드론은 높이 날았고 팀은 그 영상에 매우 만족했다.','high는 flew의 물리적 높이입니다. highly는 satisfied의 만족 정도를 꾸밉니다. 두 단어를 높다라는 한 뜻으로 묶어 바꾸어 쓰지 않습니다.','fly high · highly effective · highly recommended',['flew high','highly satisfied']),
lesson('④ -ly로 끝나도 형용사인 단어','friendly와 costly는 명사를 꾸미는 대표적인 -ly 형용사입니다. 끝 모양만 보고 부사로 분류하지 말고 실제로 무엇을 꾸미는지 확인합니다.','A friendly colleague helped us avoid a costly mistake.','친절한 동료가 우리가 큰 대가가 드는 실수를 피하도록 도왔다.','friendly는 명사 colleague를, costly는 명사 mistake를 꾸밉니다. 둘 다 helped나 avoid의 방식을 나타내는 부사가 아닙니다.','a friendly colleague · a costly mistake',['friendly colleague','costly mistake']),
lesson('⑤ 비슷한 철자도 뜻이 다른 결합으로 암기','late/lately와 close/closely도 단순한 형용사→부사 변화가 아닙니다. 아래처럼 자주 쓰는 짧은 결합의 뜻을 함께 외우면 보기의 품사가 같아도 구별할 수 있습니다.','He arrived late. Lately, we have been monitoring the schedule closely.','그는 늦게 도착했다. 최근 우리는 일정을 면밀히 점검하고 있다.','late는 arrived의 늦은 시점, lately는 최근이라는 기간을 나타냅니다. closely는 monitoring을 면밀히라는 방식으로 꾸밉니다. stand close는 물리적으로 가까이 서 있다는 뜻입니다.','arrive late · lately = 최근에 · stand close · monitor closely',['arrived late','Lately','monitoring the schedule closely'])];
n[2].quickRecallTables[0].rows.push(['arrive late','부사 late · 늦게 도착하다'],['lately','부사 · 최근에 (late와 뜻 다름)'],['stand close','부사 close · 가까이 서다'],['monitor closely','부사 closely · 면밀히 점검하다']);
n[3].focusLessons=[
lesson('① whose는 소유수식과 절 연결을 함께','빈칸 뒤에 복수 명사가 있다는 이유로 those를 고르지 않습니다. 뒤 문장이 앞 명사를 설명하는 관계절인지, 그 안의 명사가 앞 명사에 속하는지 확인합니다.','The museum opened an exhibition whose artifacts attract many visitors.','박물관은 전시 유물들이 많은 관람객을 끄는 전시회를 열었다.','주절은 The museum + opened + an exhibition입니다. 관계절의 주어는 whose artifacts, 동사는 attract입니다. whose는 artifacts가 exhibition에 속한다는 관계를 만들고 두 부분을 연결합니다. those artifacts는 복수 명사구일 뿐 이 자리를 관계절로 연결하지 못합니다.','명사 + whose + 명사 + 관계절의 나머지',['an exhibition','whose artifacts','attract']),
lesson('② those who와 those with는 뒤 덩어리가 다름','those는 “그 사람들/그것들”을 가리키는 복수 대명사입니다. 사람을 조건으로 좁힐 때 뒤에 who가 이끄는 관계절이나 with가 이끄는 전치사구가 붙을 수 있습니다.','Those who have scheduling conflicts may leave early. Those with scheduling conflicts may leave early.','일정이 겹치는 사람들은 일찍 떠나도 된다. 두 문장은 같은 대상을 두 구조로 설명한다.','첫 문장의 who have scheduling conflicts는 those를 꾸미는 관계절입니다. 둘째의 with scheduling conflicts는 동사 없는 전치사구입니다. 두 주절의 동사구는 may leave입니다. “대명사는 수식받을 수 없다”로 외우지 않습니다.','those who + 복수동사 ↔ those with + 명사구',['Those who have','Those with scheduling conflicts','may leave']),
lesson('③ that/those of는 대신하는 명사의 수','비교에서 같은 명사를 되풀이하지 않으려고 that/those로 대신합니다. of 뒤 명사가 아니라 생략되어 대신하는 명사가 하나인지 여러 개인지가 기준입니다.','The price is lower than that of the competing model. Our prices are lower than those of competing brands.','그 가격은 경쟁 모델의 가격보다 낮다. 우리 가격들은 경쟁 브랜드의 가격들보다 낮다.','첫 that은 단수 price를, 둘째 those는 복수 prices를 대신합니다. of the competing model/of competing brands는 어느 가격인지 덧붙일 뿐 that/those의 수를 결정하는 기준이 아닙니다.','price → that of · prices → those of',['price','that of','prices','those of']),
lesson('④ a number와 the number는 주어 중심이 다름','두 표현 뒤에는 모두 복수 명사가 옵니다. a number of는 “여러 ~”이므로 여러 대상을 주어로 보고, the number of는 “~의 수”라는 단수 개념을 주어로 봅니다.','A number of orders are awaiting approval; the number of pending orders is increasing.','여러 주문이 승인을 기다리고 있다. 대기 중인 주문의 수는 증가하고 있다.','앞절 주어 a number of orders는 여러 주문을 뜻하므로 are, 뒤절은 단수 number가 주어 중심이므로 is입니다. 바로 앞 orders의 -s만 보고 두 동사를 모두 복수로 고르지 않습니다.','a number of + 복수명사 + 복수동사 ↔ the number of + 복수명사 + 단수동사',['A number of orders are','the number of pending orders is'])];
n[3].quickRecallTables=[{title:'소유·대용·수일치 · 구별해서 암기',headers:['외울 결합','뜻 · 결정 단서'],rows:[['명사 + whose + 명사','소유수식 + 관계절 연결'],['those who + 복수동사','~하는 사람들 · 뒤에 관계절'],['those with + 명사구','~을 가진 사람들 · 뒤에 전치사구'],['that of','단수 명사를 대신하는 비교 대용'],['those of','복수 명사를 대신하는 비교 대용'],['a number of + 복수명사 + 복수동사','여러 ~ · orders are'],['the number of + 복수명사 + 단수동사','~의 수 · number is'],['each of the + 복수명사 + 단수동사','그중 각각 · each is'],['one of the + 복수명사 + 단수동사','그중 하나 · one is'],['both of the + 복수명사 + 복수동사','둘 다 · both are']]}];
})();
