(function(){var c=window.HANQ_TOEIC_GRAMMAR_DATA.chapters[0];
c.complementFocus=true;
c.focusLessons.unshift({title:'★ 낯선 보어 동사: 형용사 O · 부사 X',concept:'상태를 설명하는 보어 자리에서는 형용사를 고릅니다. prove effective는 “효과적인 것으로 드러나다”, be deemed necessary는 “필요하다고 판단되다”, be declared safe는 “안전하다고 선언되다”입니다. 이 세 결합을 형용사까지 통째로 외웁니다.',en:'The method proved effective. The review was deemed necessary. The site was declared safe.',ko:'그 방법은 효과적인 것으로 드러났다. 검토는 필요하다고 판단되었다. 현장은 안전하다고 선언되었다.',analysis:'effective·necessary·safe는 각각 방법·검토·현장의 상태입니다. effectively·necessarily·safely로 바꾸면 그 상태를 채우지 못합니다. 단, officially declared safe처럼 동작을 꾸미는 부사는 다른 자리에 함께 쓸 수 있습니다.',remember:'prove effective · be deemed necessary · be declared safe',focus:['effective','necessary','safe']});
c.quickRecallTables.unshift({title:'★ 상태를 설명하는 보어 자리: 형용사',headers:['상태 보어 결합','형용사 O · 부사 X'],adjectiveFocus:['effective','necessary','safe','necessary','safe','false','confident','comfortable'],rows:[
['prove effective','effective O · effectively X\n효과적인 것으로 드러나다'],
['be deemed necessary','necessary O · necessarily X\n필요하다고 판단되다'],
['be declared safe','safe O · safely X\n안전하다고 선언되다'],
['deem the review necessary','necessary O · necessarily X\n검토가 필요하다고 판단하다'],
['declare the site safe','safe O · safely X\n현장이 안전하다고 선언하다'],
['prove the claim false','false O · falsely X\n주장이 틀렸음을 입증하다'],
['feel confident','confident O · confidently X\n자신감이 느껴지다'],
['feel comfortable','comfortable O · comfortably X\n편안하게 느껴지다']
]});
c.quickRecallEvidence='★ 보어 동사 결합은 사용자가 직접 밝힌 혼동을 사전으로 대조했습니다. 자체 예문이며 실제 100제 결과를 조회했다는 뜻은 아닙니다. prove + 형용사는 주어의 상태, deem/declare/prove + 목적어 + 형용사는 목적어의 상태를 설명합니다. 이미 아는 keep/find/consider/leave/make/call도 이 보어 구문에서는 + 목적어 + 형용사까지 묶습니다. 이 동사 뒤가 언제나 형용사라고 일반화하지 않습니다.';
c.quickRecallSources=c.quickRecallSources.concat([{title:'Oxford · prove: 형용사 보어',url:'https://www.oxfordlearnersdictionaries.com/us/definition/english/prove'},{title:'Oxford · deem: 형용사 보어',url:'https://www.oxfordlearnersdictionaries.com/definition/english/deem'},{title:'Oxford · declare: 형용사 보어',url:'https://www.oxfordlearnersdictionaries.com/definition/english/declare'},{title:'Oxford · feel confident',url:'https://www.oxfordlearnersdictionaries.com/us/definition/english/confident'},{title:'Oxford · feel comfortable',url:'https://www.oxfordlearnersdictionaries.com/us/definition/english/comfortable'}]);
})();
