ly.focusLessons=[{title:'① 같은 부사여도 뜻이 달라진다',concept:'hard/hardly는 열심히와 거의 ~않다, high/highly는 실제 높이와 높은 정도·평가를 대비합니다. -ly를 단순히 부사 만드는 표시로만 보면 뜻을 반대로 읽을 수 있습니다.',en:'The staff worked hard, but they hardly had time for lunch. The crane lifted the load high; the operator was highly skilled.',ko:'직원들은 열심히 일했지만 점심 먹을 시간은 거의 없었다. 기중기는 짐을 높이 들었고 운전자는 매우 능숙했다.',analysis:'hard는 일한 노력, hardly는 시간이 거의 없음을 뜻합니다. high는 실제 높이, highly는 skilled의 능숙한 정도입니다. high/highly의 직접 질문을 중심으로 관련 대비를 함께 외우며, 모든 쌍이 실제 오답이라는 뜻은 아닙니다.',remember:'work hard ↔ hardly have time · lift high ↔ highly skilled',focus:['hard','hardly','high','highly']},{title:'② 뜻이 맞는 결합까지 같이 외우기',concept:'late/lately는 늦게와 최근에, near/nearly는 가까이와 거의를 구별합니다. close/closely는 대표적으로 거리와 면밀함·긴밀함, free/freely는 무료와 자유로움, wide/widely는 활짝 열린 상태와 넓은 분포·차이를 대비합니다. 뜻이 겹치는 다른 용법도 있으므로 아래 결합의 뜻으로 익힙니다.',en:'The truck arrived late. Orders have increased lately. Read the terms closely; keep your badge close at hand.',ko:'트럭이 늦게 도착했다. 최근 주문이 늘었다. 조건을 면밀히 읽고 출입증은 가까이 두세요.',analysis:'late는 도착 지연, lately는 최근의 증가입니다. closely는 조건을 읽는 면밀함, close at hand는 가까운 위치입니다. late/lately 등을 현재완료 전용이나 거리 전용으로 절대화하지 않습니다.',remember:'arrive late ↔ lately · close at hand ↔ read closely',focus:['late','lately','closely','close at hand']}];
