      "id": "cn-adverb",
      "title": "Then·Therefore·However·If so: 앞뒤 관계를 고르기",
      "concept": "보기의 구조가 모두 가능하면 앞뒤 관계를 봅니다. Then은 다음 순서, Therefore·Accordingly는 원인 뒤 결과·대응, However는 반대 측면입니다. If so는 if that is so를 줄인 조건 표현으로 앞의 긍정 조건을 받습니다. 뒤에 쉼표가 있어도 접속부사 한 단어라고 분류하지 않습니다. therefore·however 같은 부사는 문중에도 오며 쉼표가 항상 필수인 것은 아닙니다. 아래는 같은 시식·업체 선정 상황을 각각 다른 관계로 구성한 예문입니다.",
